function CompeteChangeRoleDialog:RefreshUI()
    local uiTable = {
        {
            oneGoodNode = self.FirstOneGoodNode,
            twoGoodNode = self.FirstTwoGoodNode,
            oneTitle = self.FirstOneTitle,
            twoTitle = self.FirstTwoTitle,
            musicText = self.FirstTextMusic
        },
        {
            oneGoodNode = self.SecondOneGoodNode,
            twoGoodNode = self.SecondTwoGoodNode,
            oneTitle = self.SecondOneTitle,
            twoTitle = self.SecondTwoTitle,
            musicText = self.SecondTextMusic
        }
    }
    local refreshNode = function(gameObject, goodsData)
        local GoodsNodeMBPath = "Game.Behaviours.GoodNodeMB" -- 物品 Node 的 脚本路径
        ---@type GoodNodeMB
        local luaEnv = CfUtils.GetLuaScr(gameObject, GoodsNodeMBPath)
        if luaEnv then
            local everyDayGood = goodsData
            luaEnv:Reload({
                goodsId = everyDayGood.goodsId,
                text = "x".. everyDayGood.num ,
                isShowNo = true
            })
            luaEnv:SetClickCallback(function(goodsId)
                local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(everyDayGood.goodsId)
                if isTable(vo) then
                    GameUtils.ShowCommonTipsBoard(gameObject, vo.name, vo.desc, vo.quality, vo.id)
                end
            end)
        end
    end
    local activityConf = self.comp:GetActivityConf()
    local rankRewards = activityConf.rankRewards
    local winReward = activityConf.winReward
    local songName = activityConf.songName or {}
    local rank = activityConf.rank

    for i, v in pairs(uiTable) do
        local rankRewardGood = rankRewards[i]
        local winReward = winReward[i]
        refreshNode(v.oneGoodNode, rankRewardGood)
        refreshNode(v.twoGoodNode, winReward)
        CfUtils.FillText(v.oneTitle, string.format(localize("排名%s奖励") , rank))
        CfUtils.FillText(v.twoTitle, localize("最终胜利奖励"))
        CfUtils.FillText(v.musicText , songName[i] or "")
    end

end

function CompeteChangeRoleDialog:CompeteChangeRoleClick(index)
    if self.changeIng then
        return
    end
    local peopleId = checkInt(self.comp:GetPlayerPeopleId())
    if peopleId > 0 then
        localize("已经选择了喜欢角色")
        return
    end

    local activityConf = self.comp:GetActivityConf()
    local peopleId = activityConf.people[index]
    GameUtils.Request(Interfaces.ActivityUserPkChosePeople, { activityUuid = self.comp:GetActivityUuid(), peopleId = peopleId }, function(request, response)
        if checkNumber(response.errCode) == 0 then
            GameUtils.Request(Interfaces.ActivityUserPkHome, { activityUuid = self.comp:GetActivityUuid() }, function(request, response)
                self.changeIng = true
                if checkNumber(response.errCode) == 0 then
                    self.changeIng = true
                    local data = response.data
                    data.activityUuid = self.comp:GetActivityUuid()
                    GameUtils.RemoveEntityCompByType(ECSComponentType.Constants.CompeteComponent)
                    self.comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.CompeteComponent)
                    self.comp:Initial(data)
                    -- 播放开始故事剧情
                    local activityConf = self.comp:GetActivityConf()
                    local startStoryId = activityConf.startStoryId
                    local ChapterUtils = import('Game.Chapter.ChapterUtils')
                    ChapterUtils.ProcessChapter(startStoryId, function(go)
                        self.controller.gameObject.transform.localPosition = Vector3(9999, 9999, 9999)
                        CS.UINavigationBarRoot.Instance:SetActive(false)
                        self.comp:SetEnterStartStoryId()
                        self._plotGo = go
                    end, function()

                        self.closeCo = cs_coroutine.start(function()
                            local KTool = CS.Engine.Lib.KTool
                            self.controller.gameObject.transform.localPosition = Vector3(0, 0, 0)
                            cs_coroutine.yield_return(Yielders.EndOfFrame)
                            KTool.SafeDelete(self._plotGo)
                            local day = os.date("%Y%m%d")
                            local startDay = os.date("%Y%m%d" , self.comp:GetStartTime())
                            if day == startDay then
                                self.comp:SetCurentDayEnter()
                            end
                            local UIModule = CS.Engine.UI.UIModule
                            CS.UINavigationBarRoot.Instance:SetActive(true)
                            UIModule.OpenDialog({ id = self.comp:GetPrefabDialogConf().MAIN_DIALOG , parameters = { isChooseRole = true } },{{id = Constants.UITypeIds.UIActivityMainDialog }})
                            UIModule.CloseDialog(self.controller)
                        end)
                    end)
                end
            end)
        end
    end)
end

function CompeteChangeRoleDialog:PlayMusicIndex(index)
    for i, v in pairs(self.roleVoices) do
        if index ~= v.index then
            if v.status == PLAY_STATUS.PLAYING then
                if v.musicId then
                    CriWareUtils.StopById(v.musicId)
                end
                v.status = PLAY_STATUS.STOP
                v.node.Status = PLAY_STATUS.STOP
                KTool.SetActive(v.musicNode , false)
            end
        else
            if v.status == PLAY_STATUS.PLAYING then
                if v.musicId then
                    CriWareUtils.StopById(v.musicId)
                end
                v.status = PLAY_STATUS.STOP
                v.node.Status = PLAY_STATUS.STOP
                KTool.SetActive(v.musicNode , false)
            else
                if v.musicId then
                    CriWareUtils.PlayMusicById(v.musicId)
                end
                v.status = PLAY_STATUS.PLAYING
                v.node.Status = PLAY_STATUS.PLAYING
                KTool.SetActive(v.musicNode , true)
            end
        end
    end

    local isPlaying = false
    for i, v in pairs(self.roleVoices) do
        if v.status == PLAY_STATUS.PLAYING then
            isPlaying = true
            break
        end
    end
    if not isPlaying then
        CriWareUtils.PlayRandomBGMFromCDList()
    end
end

